                            }
                        }
                    }
                }
            }
            prefixSum += plate;
        }

        int answer = 0;
        for (int value = 0; value <= maxValue; value++) {
            if (dp[k][value] <= t) {
                answer = value;
            }
        }

        System.out.println(answer);
    }
